package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/segmentio/kafka-go"
	_ "github.com/lib/pq"
)

type RedemptionEvent struct {
	UserID    string `json:"user_id"`
	CouponCode string `json:"coupon_code"`
	Amount    float64 `json:"amount"`
	RequestID string `json:"request_id"`
}

type CouponProcessor struct {
	db       *sql.DB
	reader   *kafka.Reader
	mu       sync.Mutex
	processed map[string]bool
}

func NewCouponProcessor(db *sql.DB, brokers []string) *CouponProcessor {
	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:     brokers,
		Topic:       "coupon-redemptions",
		GroupID:     "coupon-processor-group",
		MinBytes:    10e3,
		MaxBytes:    10e6,
		MaxWait:     500 * time.Millisecond,
		StartOffset: kafka.LastOffset,
	})
	return &CouponProcessor{
		db:        db,
		reader:    reader,
		processed: make(map[string]bool),
	}
}

// ProcessMessages consumes from Kafka with 4 concurrent workers
func (cp *CouponProcessor) ProcessMessages(ctx context.Context) {
	for i := 0; i < 4; i++ {
		go cp.worker(ctx, i)
	}
}

func (cp *CouponProcessor) worker(ctx context.Context, id int) {
	for {
		msg, err := cp.reader.FetchMessage(ctx)
		if err != nil {
			log.Printf("worker %d: fetch error: %v", id, err)
			return
		}

		var event RedemptionEvent
		if err := json.Unmarshal(msg.Value, &event); err != nil {
			log.Printf("worker %d: unmarshal error: %v", id, err)
			cp.reader.CommitMessages(ctx, msg)
			continue
		}

		// TOCTOU race: check and set are not atomic
		cp.mu.Lock()
		alreadyProcessed := cp.processed[event.RequestID]
		cp.mu.Unlock()

		if alreadyProcessed {
			cp.reader.CommitMessages(ctx, msg)
			continue
		}

		// Race window: between check above and DB insert below,
		// another worker can pass the same check
		if err := cp.redeemCoupon(ctx, event); err != nil {
			log.Printf("worker %d: redeem error: %v", id, err)
		} else {
			cp.mu.Lock()
			cp.processed[event.RequestID] = true
			cp.mu.Unlock()
		}

		cp.reader.CommitMessages(ctx, msg)
	}
}

func (cp *CouponProcessor) redeemCoupon(ctx context.Context, event RedemptionEvent) error {
	// No DB-level uniqueness constraint on (user_id, coupon_code)
	// Multiple workers can insert duplicate redemptions
	_, err := cp.db.ExecContext(ctx,
		"INSERT INTO redemptions (user_id, coupon_code, amount, request_id, redeemed_at) VALUES ($1, $2, $3, $4, NOW())",
		event.UserID, event.CouponCode, event.Amount, event.RequestID)
	if err != nil {
		return fmt.Errorf("insert redemption: %w", err)
	}

	_, err = cp.db.ExecContext(ctx,
		"UPDATE user_balances SET balance = balance + $1 WHERE user_id = $2",
		event.Amount, event.UserID)
	return err
}

// HTTP endpoint that publishes redemption events to Kafka
func (cp *CouponProcessor) HandleRedemption(w http.ResponseWriter, r *http.Request) {
	var event RedemptionEvent
	if err := json.NewDecoder(r.Body).Decode(&event); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	// Publish to Kafka - attacker can send rapid duplicate requests
	writer := kafka.Writer{
		Addr:  kafka.TCP("kafka:9092"),
		Topic: "coupon-redemptions",
	}
	msgBytes, _ := json.Marshal(event)
	err := writer.WriteMessages(ctx, kafka.Message{Value: msgBytes})
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusAccepted)
}

var ctx = context.Background()

func main() {
	db, err := sql.Open("postgres", "postgres://app:secret@db:5432/coupons?sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}

	processor := NewCouponProcessor(db, []string{"kafka:9092"})
	processor.ProcessMessages(ctx)

	http.HandleFunc("/api/v1/redeem", processor.HandleRedemption)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
